CREATE TEMPORARY VIEW dwd_raw_data_${grass_region_without_quote} AS
SELECT
    COALESCE(platform, '') AS platform
    ,COALESCE(layout_variant, '') AS layout_variant
    ,COALESCE(app_version, '') AS app_version
    ,COALESCE(dre_version, '') AS dre_version
    ,COALESCE(original_operation, '') AS operation
    ,COALESCE(search_session_id, '') AS search_session_id
    ,is_cache
    ,TRANSFORM(stages_duration, x -> FROM_JSON(x, 'STRUCT<parent_stage:STRING,stage:STRING,category_level:INT,duration:BIGINT,client_type:STRING>')) AS stages
    ,total_duration
    ,server_cost
    ,request_pack_size
    ,response_pack_size
FROM
    srdi_mart.dwd_sr_data_warehouse_search
WHERE
    grass_region = ${grass_region}
    AND local_date = ${local_date}
    AND page_type IN ('global_search', 'search_prefill', 'search_in_pdp')
    AND user_id > 0
    AND platform_implementation = 'dre'
    AND REGEXP_LIKE(app_version, '^[0-9][0-9]?\.[0-9][0-9]?\.[0-9][0-9]?$')
    AND REGEXP_LIKE(dre_version, '^[0-9][0-9]?\.[0-9][0-9]?\.[0-9][0-9]?$')
    AND operation = 'click'
    AND original_operation IN ('action_first_page_performance', 'action_pagination_performance', 'action_filter_performance')
    AND platform IN ('ios_app', 'android_app')
    AND SIZE(stages_duration) > 0;

