CREATE TEMPORARY VIEW dwd_raw_data_explode_stages_${grass_region_without_quote} AS
SELECT
    platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,operation
    ,search_session_id
    ,is_cache
    ,stage_detail.stage AS stage
    ,COALESCE(stage_detail.category_level, 'NULL') AS category_level
    ,COALESCE(stage_detail.parent_stage, 'NULL') AS parent_stage
    ,COALESCE(stage_detail.client_type, 'NULL') AS client_type
    ,stage_detail.duration AS duration
FROM
    dwd_raw_data_version_filtered_${grass_region_without_quote}
