CREATE TEMPORARY VIEW dws_stage_duration_metrics_${grass_region_without_quote} AS
SELECT
    platform
    ,IF(GROUPING(layout_variant) = 1, '__ALL__', layout_variant) AS layout_variant
    ,IF(GROUPING(app_version) = 1, '__ALL__', app_version) AS app_version
    ,IF(GROUPING(dre_version) = 1, '__ALL__', dre_version) AS dre_version
    ,operation
    ,stage
    ,category_level
    ,parent_stage
    ,APPROX_PERCENTILE(duration, ARRAY(0.8, 0.9, 0.95, 0.99)) AS duration_pcts
FROM
    dwd_raw_data_explode_stages_${grass_region_without_quote}
WHERE
    -- category_level & parent_stage live on dre_version >= 1.57.4 & app-version >= 3.27.0
    (
        CAST(SPLIT(dre_version, '\\.')[0] AS INT) > 1
        OR (CAST(SPLIT(dre_version, '\\.')[0] AS INT) = 1 AND CAST(SPLIT(dre_version, '\\.')[1] AS INT) > 57)
        OR (CAST(SPLIT(dre_version, '\\.')[0] AS INT) = 1 AND CAST(SPLIT(dre_version, '\\.')[1] AS INT) = 57 AND CAST(SPLIT(dre_version, '\\.')[2] AS INT) >= 4)
    )
GROUP BY
    platform, CUBE(layout_variant, app_version, dre_version), operation, stage, category_level, parent_stage;

