        WHEN operation = 'action_pagination_performance' THEN SUM(IF(stage = 'load_more', duration, 0))
            - SUM(IF(stage IN ('prepare_render_data', 'prepare_search_params', 'fetch_items', 'parse_response_data'), duration, 0))
        WHEN operation = 'action_filter_performance' THEN SUM(IF(stage = 'filter_refresh', duration, 0)) - SUM(IF(category_level = 1, duration, 0))
    END AS duration
FROM
    dwd_raw_data_explode_stages_${grass_region_without_quote}
WHERE -- Restrict dre_version >= 1.57.4 AND dre_version < 1.67.0
    (CAST(SPLIT(dre_version, '\\.')[0] AS INT) = 1 AND CAST(SPLIT(dre_version, '\\.')[1] AS INT) > 57 AND CAST(SPLIT(dre_version, '\\.')[1] AS INT) < 67)
    OR (CAST(SPLIT(dre_version, '\\.')[0] AS INT) = 1 AND CAST(SPLIT(dre_version, '\\.')[1] AS INT) = 57 AND CAST(SPLIT(dre_version, '\\.')[2] AS INT) >= 4)
GROUP BY
    1,2,3,4,5,6,7,8
UNION ALL
