CREATE TEMPORARY VIEW dws_runtime_metrics_${grass_region_without_quote} AS
SELECT
    platform
    ,layout_variant
    ,app_version
    ,dre_version
    ,operation
    ,stage
    ,client_type
    ,APPROX_PERCENTILE(duration, ARRAY(0.8, 0.9, 0.95, 0.99)) AS duration_pcts
