    ,IF(GROUPING(dre_version) = 1, '__ALL__', dre_version) AS dre_version
    ,operation
    ,stage
    ,NULL AS client_type
    ,APPROX_PERCENTILE(duration, ARRAY(0.8, 0.9, 0.95, 0.99)) AS duration_pcts
FROM
    dwd_runtime_metrics_${grass_region_without_quote}
GROUP BY GROUPING SETS (
    (platform, app_version, dre_version, operation, stage)
    ,(platform, layout_variant, dre_version, operation, stage)
    ,(platform, layout_variant, app_version, operation, stage)
    ,(platform, dre_version, operation, stage)
    ,(platform, layout_variant, operation, stage)
    ,(platform, app_version, operation, stage)
    ,(platform, operation, stage)
);

