CREATE TEMPORARY VIEW dwd_total_duration_and_be_statistics_for_all_op_${grass_region_without_quote} AS
SELECT
-- Apply group by search_session_id and sum metrics
-- Before approx pct for operation = __ALL__ for these metrics
    platform
    ,IF(GROUPING(layout_variant) = 1, '__ALL__', layout_variant) AS layout_variant
    ,IF(GROUPING(app_version) = 1, '__ALL__', app_version) AS app_version
    ,IF(GROUPING(dre_version) = 1, '__ALL__', dre_version) AS dre_version
    ,search_session_id
    ,SUM(CASE
        WHEN operation IN ('action_first_page_performance', 'action_filter_performance') THEN total_duration
        WHEN operation = 'action_pagination_performance'
            THEN AGGREGATE(FILTER(stages, x -> x.stage = 'load_more_item_exposure'), CAST(0 AS BIGINT), (acc, stage_detail) -> acc + GREATEST(stage_detail.duration, 0))
        ELSE 0
    END) AS total_duration
    ,SUM(server_cost) AS server_cost
    ,SUM(request_pack_size) AS request_pack_size
    ,SUM(response_pack_size) AS response_pack_size
FROM
    dwd_raw_data_version_filtered_${grass_region_without_quote}
GROUP BY 
    platform, CUBE(layout_variant, app_version, dre_version), search_session_id;

